  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Sorunuz veya sorununuz mu var? <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a> adresine ulaşın.</p><p class=\"font-semibold text-emerald-900\">İadeniz Stripe üzerinden başlatıldı.</p><p class=\"text-emerald-800 mt-1\">Kart iadeleri genellikle yaklaşık <strong>5–10 iş günü</strong> içinde ulaşır (bankaya göre değişebilir). Olağan süre içinde ulaşmazsa <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a> adresine e-posta gönderin.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Bu dersin ücreti Tutlio Stripe üzerinden ödenmiş görünmüyor (örn. banka havalesi veya nakit). Buradan otomatik iade yapılamaz.</p><p class=\"mt-2\">İade için öğretmeniniz <strong>{tutor}</strong> ile iletişime geçin. Rezervasyonlarınızdaki veya doğrudan öğretmenin verdiği e-posta adresini ya da diğer iletişim bilgilerini kullanın.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Bu dersin ücreti Tutlio Stripe üzerinden ödenmiş görünmüyor (örn. banka havalesi veya nakit). Buradan otomatik iade yapılamaz.</p><p class=\"mt-2\">Bir kurum üzerinden ders aldığınız için <strong>kurum yöneticisine</strong> ulaşın (öğretmeniniz aracılığıyla veya kurumun yayımladığı iletişim bilgilerini kullanarak).</p>",
