  "orgTutorPolicy.title": "Öğretmenler için iç kurallar",
  "orgTutorPolicy.intro": "Platformu kullanmadan önce lütfen kurumun iç kurallarını inceleyin.",
  "orgTutorPolicy.acceptBtn": "Anladım",
  "orgTutorPolicy.viewBtn": "İç kuralları görüntüle",
  "orgTutorPolicy.s1Title": "1. Genel hükümler",
  "orgTutorPolicy.s1Body": "Bu kurallar, öğretmen veya özel ders öğretmeni (“Öğretmen”) olarak Tutlio platformunu (“Platform”) kullanımınızı düzenler. Temsil ettiğiniz eğitim ajansı, okul veya özel ders merkezi (“Kurum”) tarafından Platformu kullanmaya davet edildiniz. Platformun teknik bakımı ve desteği MB Tutlio tarafından sağlanır. Hesabınızı kullanarak bu Kuralları ve Gizlilik Politikasını kabul edersiniz.",
  "orgTutorPolicy.s2Title": "2. Hesap yönetimi ve programlar",
  "orgTutorPolicy.s2Intro": "Platform, öğrencilerle ders saatlerini ayarlamak için zaman harcamanıza gerek kalmayacak şekilde tasarlanmıştır.",
  "orgTutorPolicy.s2Link": "Benzersiz bağlantı: Size, verdiğiniz branşlara göre kişisel bir ders rezervasyonu bağlantısı atanır. Öğrenciler ders planlamak için bu bağlantıyı kullanır.",
  "orgTutorPolicy.s2Calendar": "Takvim eşitleme: Müsaitliğiniz doğrudan Google Calendar entegrasyonunuza bağlıdır (2 yönlü eşitleme). Takviminizde gösterilen müsait zamanın doğru ve güncel olmasından kişisel olarak sorumlusunuz. Platform, takviminizde dolu olarak işaretlenmiş saatlere öğrencilerin rezervasyon yapmasına izin vermez.",
  "orgTutorPolicy.s2Security": "Hesap güvenliği: Hesabınız kişiseldir. Giriş bilgilerinizi güvenli tutmalı ve üçüncü kişilerle paylaşmamalısınız.",
  "orgTutorPolicy.s3Title": "3. Ders iptalleri ve bekleme listesi",
  "orgTutorPolicy.s3Intro": "Platform, programınızı en iyi şekilde değerlendirmenize ve boş saatlerden kaçınmanıza yardımcı olur:",
  "orgTutorPolicy.s3Auto": "Bir öğrenci dersi iptal ederse Platform, bekleme listenizdeki diğer öğrencilere boşalan saati sunan bir bildirim (SMS/e-posta) otomatik olarak gönderir. Sizin ek işlem yapmanız gerekmez.",
  "orgTutorPolicy.s3Rules": "Ders iptal kuralları (dersin ne kadar önceden iptal edilebileceği ve sonuçları) Kurumunuz tarafından belirlenir.",
  "orgTutorPolicy.s4Title": "4. Finans ve ödemeler",
  "orgTutorPolicy.s4Intro": "Fatura düzenleme veya velilerden ödeme toplama konusunda endişelenmenize gerek yoktur:",
  "orgTutorPolicy.s4Advance": "Dersleriniz için tüm öğrenci veya veli ödemeleri Platform üzerinden önceden tahsil edilir ve doğrudan Kurumunuza aktarılır.",
  "orgTutorPolicy.s4Confirmed": "Bir dersi yalnızca sistemde onaylandığında (yani ücreti zaten tahsil edildiğinde) verirsiniz.",
  "orgTutorPolicy.s4Contact": "Ücretiniz, ödeme takviminiz ve diğer mali konular için lütfen doğrudan Kurumunuzun yöneticisine ulaşın. MB Tutlio, Öğretmenlerle doğrudan mali işlem yapmaz.",
  "orgTutorPolicy.s5Title": "5. Öğrenci verilerinin korunması (GDPR)",
  "orgTutorPolicy.s5Intro": "Öğretmen olarak öğrencilerin kişisel verilerine, kurum içi notlara ve öğrenme materyallerine erişirsiniz. Şunları taahhüt edersiniz:",
  "orgTutorPolicy.s5Use": "Bu verileri yalnızca dersleri düzenlemek ve vermek için kullanmak.",
  "orgTutorPolicy.s5NoCopy": "Öğrencilerin veya velilerin iletişim bilgilerini Platform dışına kopyalamamak, dışa aktarmamak veya dağıtmamak.",
  "orgTutorPolicy.s5Notes": "Yalnızca sizin ve Kurum yönetiminin görebildiği, öğrencilere veya velilere görünmeyen kurum içi kayıtları (öğrenci ilerlemesine ilişkin notlar) korumak.",
  "orgTutorPolicy.s5Termination": "Kurum ile çalışma ilişkiniz sona erdiğinde bu verilere erişiminiz derhal kaldırılır.",
  "orgTutorPolicy.s6Title": "6. Teknik işleyiş ve sorumluluğun sınırlandırılması",
  "orgTutorPolicy.s6Body": "Platformun hukuka aykırı amaçlarla kullanılması, ders materyallerinde zararlı bağlantıların dağıtılması veya sistemin başka şekilde aksatılması yasaktır. MB Tutlio, Platformun işleyişini ve teknik bakımını sağlar; ancak internet bağlantınızdan, cihaz arızalarından veya yanlış yapılandırılmış Google Calendar ayarlarından kaynaklanan kesintilerden sorumlu değildir.",
  "orgTutorPolicy.s7Title": "7. Destek ve iletişim",
  "orgTutorPolicy.s7Org": "Ders programları, ücretler, öğrenci atamaları veya iş organizasyonu hakkındaki sorular için Kurum yöneticinize ulaşın.",
  "orgTutorPolicy.s7Tech": "Platformdaki teknik hataları (takvim eşitlemesinin çalışmaması, bildirim alınmaması) Kurum yöneticinize bildirin. Yöneticiniz Tutlio teknik destek ekibiyle iletişime geçecektir.",
  "register.orgPolicyConsent": "Platformumuzu kullanarak kabul etmiş olursunuz:",
  "register.orgPolicyLink": "iç politikalar",
