  "quiz.info.story.company.customerType": "Özel ders kurumu ekibi",
  "quiz.info.story.company.story": "“Tutlio'dan önce ders değişiklikleri, yorumlar ve öğretmen saatleri mesajlara dağılmıştı. Şimdi tüm ekip aynı programla çalışıyor ve ay sonunda güncellemelerin peşinden koşmamız gerekmiyor.”",
