  "quiz.info.story.company.proof3": "Derslerin izlenmesi",
  "quiz.info.story.company.detail": "“En büyük fark, bizi genel bir sürece zorlamak yerine onayların, telafi derslerinin ve ücret kurallarının ekibimizin mevcut çalışma biçimine uyarlanmasıydı.”",
