  "quiz.info.story.school.customerType": "Okul yönetim ekibi",
  "quiz.info.story.school.story": "“Ekibin bir aileyi kayıttan sözleşmeye, oradan her taksite kadar takip edebileceği tek bir yer istiyorduk. Tutlio, paralel tablolar tutmadan bu devamlılığı sağlıyor.”",
