  "quiz.offer.guarantee.title": "14 günlük para iadesi garantisi",
  "quiz.offer.guarantee.body": "Tutlio size uygun değilse ilk 14 gün içinde iade isteyin. Hiçbir soru sorulmaz.",
  "quiz.offer.testimonials.eyebrow": "Günlük işlerde Tutlio",
  "quiz.offer.testimonials.title.solo": "Bağımsız öğretmenler neler fark ediyor?",
  "quiz.offer.testimonials.title.company": "Tutlio bir özel ders kurumunu nasıl destekler?",
  "quiz.offer.testimonials.title.school": "Tutlio okul yönetimini nasıl birbirine bağlar?",
  "quiz.offer.testimonials.pause": "Yorumları duraklat",
  "quiz.offer.testimonials.play": "Yorumları oynat",
  "quiz.offer.testimonials.navigation": "Bir yorum seçin",
  "quiz.offer.testimonials.goTo": "{number}. yorumu göster",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Kimya ve biyoloji öğretmeni",
  "quiz.offer.testimonial.solo.copy3": "“Herkese açık sayfa ve rezervasyonun tek bağlantıda olması yeni öğrencilerin daha hızlı karar vermesini sağlıyor. Ben de artık aynı bilgileri herkese tek tek göndermiyorum.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Fizik öğretmeni",
  "quiz.offer.testimonial.solo.copy4": "“Dersleri, değişiklikleri ve ödeme durumlarını takvimde hemen görebiliyorum. Günlük idari işler çok daha kısa ve anlaşılır hâle geldi.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Özel ders kurumu ekibi",
  "quiz.offer.testimonial.company.copy1": "“Ders değişiklikleri, öğretmen yorumları ve saatler eskiden ayrı mesajlarla geliyordu. Şimdi yönetim ekibi tüm resmi tek programda görebiliyor.”",
  "quiz.offer.testimonial.company.name2": "Bağımsız özel ders merkezi",
  "quiz.offer.testimonial.company.role2": "İşletme sahibi · 8 öğretmen",
  "quiz.offer.testimonial.company.copy2": "“Eskiden öğretmen ödemelerini hazırlamadan önce cuma akşamlarını takvimle öğretmen mesajlarını karşılaştırmaya harcardım. Tutlio ile bu kontrollerin çoğu zaten yapılmış oluyor.”",
  "quiz.offer.testimonial.company.name3": "Dil öğretimi stüdyosu",
  "quiz.offer.testimonial.company.role3": "Operasyon sorumlusu · 14 öğretmen",
  "quiz.offer.testimonial.company.copy3": "“Bir dersin zamanı değiştiğinde ekip aynı güncellemeyi hemen görüyor. Daha az takip mesajı gönderiyoruz ve veliler çok daha net yanıtlar alıyor.”",
  "quiz.offer.testimonial.company.name4": "Sınava hazırlık akademisi",
  "quiz.offer.testimonial.company.role4": "Finans koordinatörü · 22 öğretmen",
  "quiz.offer.testimonial.company.copy4": "“Öğretmen ücret kurallarımız ders türüne göre değişiyor. Bu yüzden ay sonu çok fazla manuel kontrol gerektiriyordu. Tutlio iş akışı bu süreci çok daha sakin hâle getirdi.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Okul yönetim ekibi",
  "quiz.offer.testimonial.school.copy1": "“En belirgin iyileştirme, birkaç kişiye sormadan veya ayrı dosyalara bakmadan sözleşme, imza ve ödeme durumunu görebilmek.”",
  "quiz.offer.testimonial.school.name2": "Bağımsız topluluk okulu",
  "quiz.offer.testimonial.school.role2": "Kayıt koordinatörü · 86 öğrenci",
  "quiz.offer.testimonial.school.copy2": "“Kayıt dönemi eskiden formları, veli bilgilerini ve imzalı sözleşmeleri ayrı klasörlerde takip etmek demekti. Şimdi ekibimiz her aileyi tek yerden izleyebiliyor.”",
  "quiz.offer.testimonial.school.name3": "Okul sonrası öğrenme merkezi",
  "quiz.offer.testimonial.school.role3": "Yönetici · 120 öğrenci",
  "quiz.offer.testimonial.school.copy3": "“Taksit planları ödeme takibini çok daha sakin hâle getirdi. Bir veliyle iletişime geçmeden önce listeyi elle yeniden hazırlamak yerine hangi ödemenin vadesi geldiğini görebiliyorum.”",
  "quiz.offer.testimonial.school.name4": "Sanat eğitimi okulu",
  "quiz.offer.testimonial.school.role4": "Finans koordinatörü · 9 program",
  "quiz.offer.testimonial.school.copy4": "“Muhasebe dışa aktarımı artık sözleşme ve ödemelerde kullandığımız aynı kayıtlardan geliyor. Bu yüzden ay sonunda çok daha az düzeltme gerekiyor.”",
  "quiz.offer.savings.eyebrow": "Tahmini zaman etkisi",
