  "landing.custom.badge": "Asıl fark",
  "landing.custom.title": "Çalışma biçiminize uyum sağlayan yazılım - tersi değil",
  "landing.custom.sub": "Her kurum ve ajans biraz farklı çalışır. Standart akış uymadığında Tutlio'yu sizin sürecinize göre uyarlarız - genellikle çeyrekler değil, haftalar içinde. Müşterilerimiz için hâlihazırda geliştirdiklerimizden birkaçı:",
  "landing.custom.ex1Title": "E-imzalı yıllık sözleşmeler",
  "landing.custom.ex1Desc": "Bir özel okul, velilerin yıllık sözleşmeleri elektronik olarak imzalamasını, taksitle ödemesini ve her ödemenin muhasebeye hazır bir dışa aktarımda görünmesini istiyordu. Bugün tüm döngü Tutlio içinde işliyor.",
  "landing.custom.ex2Title": "Öğretmen ücreti ve komisyon kuralları",
  "landing.custom.ex2Desc": "Bir ajans her öğretmene derse ve ders türüne göre ödeme yapıyor, üzerine şirket komisyonu ekliyordu. Kurallarını modelledik; böylece aylık öğretmen dökümleri ve faturalar otomatik oluşuyor.",
  "landing.custom.ex3Title": "Veliler için tek tıkla teklifler",
  "landing.custom.ex3Desc": "Bir kurum, ek dersleri e-postayla sunmak ve velilerin tek tıkla kabul etmesini istiyordu - hesap açmadan, çıktı almadan. Artık kabul, faturalama ve ilk ders daveti kendiliğinden ilerliyor.",
  "landing.custom.ex4Title": "Markanız, kendi sitenizde",
  "landing.custom.ex4Desc": "Bir kurum kendi logosunu ve renklerini, ayrıca sitesine gömülü bir girişi istedi; böylece öğrenciler ve veliler siteden ayrıldıklarını hissetmiyor. Tutlio artık onların markasıyla çalışıyor.",
  "landing.custom.note": "Bunların hiçbiri özel bir sürüm değil. Her uyarlama, ekibinizin zaten kullandığı ürünün parçası olur ve gelecekteki tüm güncellemeleri kapsar.",
  "landing.custom.cta": "Nasıl çalıştığınızı anlatın",
  "landing.custom.soloTitle": "Eksik bir şey mi var?",
  "landing.custom.soloNote": "Tek bir ödeme kuralından tüm iş akışına kadar, kurumlara özel özellikler geliştiriyoruz. Size zaman kazandıracak şeyi bize yazın.",
  "stats.cancellationPartTutor": "öğretmen: {count}",
  "compare.hub.badge": "Karşılaştırma",
  "compare.hub.title": "Tutlio, diğer özel ders yönetim programlarıyla karşılaştırıldığında",
  "compare.hub.subtitle": "Öğretmenlerin ve etüt merkezlerinin en sık değerlendirdiği araçlarla madde madde, dürüst karşılaştırmalar. Bir rakip size daha uygunsa bunu da söylüyoruz.",
